new_string:
// Для «живых» показаний достаточно короткого окна — не тянем сутки
// истории при каждом опросе (экономия трафика и CPU).
final lookbackMinutes = (_pollSeconds * 3 / 60).ceil().clamp(5, 30);
final series = await machines.getReadings(
  machineId,
  sensor.id,
  minutes: lookbackMinutes,
  channelIndex: sensor.config.channelIndex,
);

